('s6', 'own', 'Foldable Steel Glass, 150 ml', 'foldable-steel-glass-150-ml', 'sports', 'Travel', '<p>Collapsible stainless steel travel cup with a lid and key ring. Folds flat into your pocket or bag.</p>', '["/assets/products/foldable-steel-glass.jpg"]'::jsonb, 70, null, 178, true, true, 5),
