('s8', 'own', 'PU Leather Smart Sling Bag', 'pu-leather-smart-sling-bag', 'fashion', 'Bags', '<p>Slim crossbody sling bag in PU leather with a combination lock and a USB port for charging on the move.</p>', '["/assets/products/pu-leather-sling-bag.jpg"]'::jsonb, 225, null, 449, true, true, 5),
('s9', 'own', 'Stainless Steel Cloth Drying Rope, 10 m', 'stainless-steel-cloth-drying-rope-10-m', 'cleaning', 'Laundry', '<p>Heavy-duty 10 metre stainless steel clothesline with hooks, for balconies, terraces and outdoors. Rust resistant.</p>', '["/assets/products/steel-cloth-drying-rope.jpg"]'::jsonb, 60, null, 199, true, true, 5),
('s10', 'own', 'Gas Stove Burner Stand', 'gas-stove-burner-stand', 'kitchen', 'Gas stove accessories', '<p>Windproof burner stand that focuses the flame on your pan, saving gas and keeping small pots steady.</p>', '["/assets/products/gas-stove-burner-stand.jpg"]'::jsonb, 136, null, 299, true, true, 5),
('s11', 'own', 'Cat Dancing Ball Toy', 'cat-dancing-ball-toy', 'home', 'Pet supplies', '<p>Bouncing ball on a rope toy that keeps cats and small dogs chasing and playing.</p>', '["/assets/products/cat-dancing-ball.jpg"]'::jsonb, 70, null, 230, true, true, 5),
('s12', 'own', 'Mini Lint Roller', 'mini-lint-roller', 'cleaning', 'Lint removers', '<p>Reusable, washable lint roller for clothes, sofas and car seats. Picks up hair, lint, dust and crumbs.</p>', '["/assets/products/mini-lint-roller.jpg"]'::jsonb, 35, null, 169, true, true, 5),
('s13', 'own', 'Automatic Gel Blaster Toy Gun', 'automatic-gel-blaster-toy-gun', 'kids', 'Toy guns', '<p>Automatic gel ball blaster with goggles and water gel beads. For outdoor play with adult supervision.</p>', '["/assets/products/gel-blaster-toy-gun.jpg"]'::jsonb, 380, null, 840, true, true, 5)
